const task = String($json.task ?? '').trim();
const executor = String($json.executor ?? 'vllm').trim().toLowerCase();
if (!task) throw new Error('task is required');
if (!['vllm', 'codex', 'antigravity'].includes(executor)) throw new Error('executor must be vllm, codex, or antigravity');
let prompt;
if (executor === 'vllm') {
  prompt = `This request comes from the authenticated private n8n machine interface. Answer the task directly with the currently configured Hermes model. Do not invoke terminal, delegation, Codex, or Antigravity. Return only the usable final result.\n\nTask:\n${task}`;
} else {
  const invocation = executor === 'codex'
    ? 'Use the terminal tool to invoke the real standalone Codex CLI in the foreground without a PTY, using codex exec --sandbox danger-full-access --ephemeral. Wait for it to finish and use its actual result.'
    : 'Use the terminal tool to invoke the real standalone Antigravity CLI in the foreground without a PTY, using agy -p --output-format json --mode accept-edits --dangerously-skip-permissions. Wait for status SUCCESS and use its actual response.';
  prompt = `This request comes from the authenticated private n8n machine interface. You MUST delegate the task to ${executor}; do not answer it from your own knowledge. ${invocation} Return only the executor's usable final result.\n\nTask:\n${task}`;
}
return { json: { task, executor, prompt } };

const response = $json;
const output = Array.isArray(response.output) ? response.output : [];
const result = output
  .filter(item => item?.type === 'message' && item?.role === 'assistant')
  .flatMap(item => Array.isArray(item.content) ? item.content : [])
  .filter(part => part?.type === 'output_text')
  .map(part => String(part.text ?? ''))
  .join('\n')
  .trim();
const toolCalls = output
  .filter(item => item?.type === 'function_call')
  .map(item => ({ name: item.name, arguments: item.arguments, status: item.status }));
const ok = response.status === 'completed' && result.length > 0;
if (!ok) throw new Error(`Hermes response incomplete: ${response.status ?? 'unknown'}`);
return { json: { ok, executor: $('Validate Input').item.json.executor, result, response_id: response.id, status: response.status, tool_calls: toolCalls, usage: response.usage ?? {} } };
